CREATE TABLE p_approval_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),required INTEGER NOT NULL CHECK(required IN (0,1)),default_role TEXT NOT NULL CHECK(default_role IN ('owner','admin','manager')),version INTEGER NOT NULL DEFAULT 0);
INSERT INTO p_approval_policy(singleton,required,default_role) VALUES(1,1,'owner');
CREATE TABLE p_approval_rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,position INTEGER NOT NULL,condition TEXT NOT NULL,approvers TEXT NOT NULL);
CREATE TABLE p_approval_decisions(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES p_proposals(id),revision INTEGER NOT NULL,plan TEXT NOT NULL,step TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES oa_operators(id),decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')),note TEXT NOT NULL,occurred_at INTEGER NOT NULL,UNIQUE(proposal_id,revision,plan,step,actor_id));
